import{_ as e,o as t,c as r,a5 as l}from"./chunks/framework.BF53ZjCA.js";const g=JSON.parse('{"title":"鉴定工作流与记录","description":"","frontmatter":{"title":"鉴定工作流与记录","identification":"identification-workflow"},"headers":[],"relativePath":"zh/identification/identification-workflow.md","filePath":"zh/identification/identification-workflow.md","lastUpdated":1790876393000}'),i={name:"zh/identification/identification-workflow.md"};function n(s,a,o,d,p,h){return t(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="鉴定工作流与记录" tabindex="-1">鉴定工作流与记录 <a class="header-anchor" href="#鉴定工作流与记录" aria-label="Permalink to &quot;鉴定工作流与记录&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>专业鉴定不是寻找一个“神奇读数”，而是建立可复核的证据链。先记录样品状态， 再从低风险观察开始，逐步组合物理、光学和包裹体线索；最后明确结论的置信边界、 处理披露与是否需要实验室报告。</p><aside class="gem-identification-boundary" aria-labelledby="identification-boundary-identification-workflow-zh"><p class="gem-identification-boundary__eyebrow">IDENTIFICATION BOUNDARY</p><h2 id="identification-boundary-identification-workflow-zh">边界与安全</h2><p>本页用于学习如何组织证据，不是样品鉴定表。任何结论都必须说明观察条件、未完成的测试和样品限制；不能仅凭照片或单项读数确认天然、合成、处理、产地或价值。涉及高价值或正式披露时停止自行判断并送检。 </p></aside><h2 id="鉴定步骤" tabindex="-1">鉴定步骤 <a class="header-anchor" href="#鉴定步骤" aria-label="Permalink to &quot;鉴定步骤&quot;">​</a></h2><p><strong>1. 先记录样品与任务边界</strong></p><p>记录尺寸、重量、镶嵌状态、已知来源、可见损伤和委托目的。镶嵌石、涂油石或无法接触 的样品，应在记录中注明哪些测试无法可靠完成。</p><p><strong>2. 从无损观察开始</strong></p><p>在白光、点光源和适当放大下观察体色、透明度、光泽、切工、包裹体与光学现象；先写下 观察事实，再写候选判断，避免把名称当成观察结果。</p><p><strong>3. 按风险递进测试</strong></p><p>优先考虑折射率、偏光镜、二色镜、紫外荧光和光谱等非破坏性线索；比重测试要评估样品 是否适合浸液，划痕测试只在必要且获准时考虑。</p><p><strong>4. 交叉验证与分级结论</strong></p><p>将读数与候选品种的特征范围、处理可能性和样品限制逐项比对。结论应区分“支持候选”、 “与候选一致”和“无法排除”，不要把单项测试写成最终鉴定。</p><p><strong>5. 需要时转交实验室</strong></p><p>涉及天然/合成判断、产地意见、重大交易或保险用途时，应保留原始记录并交由具备资质的 实验室完成更高阶检测。</p><p><strong>可复制鉴定记录卡（最小版）</strong></p><table tabindex="0"><thead><tr><th>区块</th><th>记录内容</th></tr></thead><tbody><tr><td>样品与任务</td><td>样品编号、日期、操作者、送检目的、裸石/镶嵌/复合材料</td></tr><tr><td>外观事实</td><td>光源、观察方向、颜色、透明度、光泽、切工、可见包裹体与损伤</td></tr><tr><td>仪器与条件</td><td>仪器名称/型号、校准或检查状态、接触状态、环境与安全限制</td></tr><tr><td>原始读数</td><td>每次读数、范围、方向、重复次数、异常或无法读数的原因</td></tr><tr><td>解释与边界</td><td>支持候选、排除候选、无法排除项、未完成测试、是否送检</td></tr></tbody></table><p><strong>停止条件：</strong> 样品不可接触、存在表面/结构风险、读数不稳定或结论涉及天然/合成、处理、产地与价值时，不为了“得到一个名称”继续增加风险测试。</p><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><ul><li>记录“看到了什么”与“因此怀疑什么”两栏，避免观察与结论互相污染。</li><li>仪器读数应带测试条件、方向、接触状态和重复结果，不能脱离上下文比较。</li><li>结论强度必须低于证据强度：筛分结果不是鉴定证书，产地意见也不是分级。</li><li>任何破坏性测试都要先确认授权、样品价值与安全条件。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>数值</th><th>备注</th></tr></thead><tbody><tr><td>镶嵌红宝石</td><td>先做筛分，并记录无法接触的测试</td><td>镶嵌状态限制</td></tr></tbody></table><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">参考依据与证据边界</h2><p class="gem-reference-block__intro">本页内容用于学习与检索；来源用于说明知识依据，不代表仅凭本页即可完成具体样品鉴定。</p><ul><li><a href="https://www.gia.edu/gems-gemology/winter-2024-gemstone-analysis" target="_blank" rel="noreferrer">GIA：宝石实验室分析流程</a><span>标准宝石学测试、实验室工作流与实验室培育钻石分析示例</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/winter-2019-analytical-methods-geographic-origin-determination-gemstones" target="_blank" rel="noreferrer">GIA：宝石产地分析方法综述</a><span>RI/SG 作为鉴定起点，以及产地判断所需的后续分析</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/winter-2024-infrared-spectroscopy" target="_blank" rel="noreferrer">GIA：红外光谱在宝石学中的应用</a><span>光谱与原子结构、天然/合成/处理线索之间的关系</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/ruby" target="_blank" rel="noreferrer">GIA 宝石百科：红宝石</a><span>红宝石的典型 RI、双折射、比重和硬度参考</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/sapphire" target="_blank" rel="noreferrer">GIA 宝石百科：蓝宝石</a><span>蓝宝石的典型 RI、双折射、比重和硬度参考</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/emerald" target="_blank" rel="noreferrer">GIA 宝石百科：祖母绿</a><span>祖母绿的典型 RI、双折射、比重、硬度与处理/合成/仿品边界</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/spinel" target="_blank" rel="noreferrer">GIA 宝石百科：尖晶石</a><span>尖晶石的典型 RI、均质性、比重和硬度参考</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/diamond" target="_blank" rel="noreferrer">GIA 宝石百科：钻石</a><span>钻石的典型 RI、比重和硬度参考</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/zircon" target="_blank" rel="noreferrer">GIA 宝石百科：锆石</a><span>锆石的典型 RI、双折射、比重和硬度参考</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/articles/iolite-description" target="_blank" rel="noreferrer">GIA：堇青石（Iolite）描述</a><span>堇青石的强多色性与观察方向提示</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/tanzanite-description" target="_blank" rel="noreferrer">GIA：坦桑石描述</a><span>坦桑石的多色性、切磨方向、光源与热处理背景</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/peridot" target="_blank" rel="noreferrer">GIA 宝石百科：橄榄石</a><span>橄榄石典型 RI、双折射、比重和硬度参考</span><small>打开来源 ↗</small></li><li><a href="https://my.gia.edu/FAQ/gia-faq-two-green-garnet" target="_blank" rel="noreferrer">GIA FAQ：沙弗莱石与翠榴石的区别</a><span>绿色石榴石颜色重叠与矿物差异提示</span><small>打开来源 ↗</small></li></ul></aside><p><em>详见<a href="./intro.html">鉴定总览</a>。</em></p>',24)])])}const m=e(i,[["render",n]]);export{g as __pageData,m as default};
